\label{thm:main-noncompact}
Let $M$ be a noncompact rank-one symmetric space of real dimension $m=kn$.
For every bounded connected domain $\Omega\subset M$ with smooth boundary,
\begin{equation}\label{eq:main-noncompact}
  \sum_{j=1}^{m}\frac1{\mu_j(\Omega)}
  \ge \frac{m}{\mu_1(B_R)}.
\end{equation}
Equality holds if and only if $\Omega$ is a geodesic ball.

\label{ass:compact-localization}
The domain $\Omega$ is contained in a geodesic ball
$B_{i(M)/4}(q)$ of a compact rank-one symmetric space $M$.

\label{thm:main-compact}
Let $M$ be a compact rank-one symmetric space of real dimension $m=kn$, and
let $\Omega$ satisfy \cref{ass:compact-localization}.  Then
\begin{equation}\label{eq:main-compact}
  \sum_{j=1}^{m}\frac1{\mu_j(\Omega)}
  \ge \frac{m}{\mu_1(B_R)}
\end{equation}
with equality if and only if $\Omega$ is a geodesic ball, provided one of
 the following conditions holds:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
  \item $k=1$;
  \item $n=1$;
  \item $1<k<m$ and
  \begin{equation}\label{eq:radius-condition}
     \cot^2 R\ge k-1.
  \end{equation}
\end{enumerate}

\label{cor:compact-models}
Under \cref{ass:compact-localization}, the full estimate
\eqref{eq:main-compact} holds for every domain in $\mathbb{C}\mathrm P^n$ and $\mathbb{H}\mathrm P^n$.
For $M=\mathbb{O}\mathrm P^2$, it holds whenever
\begin{equation}\label{eq:Rstar}
  R\le R_*:=\arctan\frac1{\sqrt7}.
\end{equation}
In all these cases equality characterizes geodesic balls.

\label{thm:hopf-balanced-intro}
Under \cref{ass:compact-localization}, suppose the chosen Weinberger center
 satisfies $\Pi Z=0$.  Then the full estimate \eqref{eq:main-compact}
 holds, with equality only for geodesic balls, without any additional
 restriction on $R$.

\label{lem:radial-monotonicity}
The function $G$ is nondecreasing and $G'(r)=0$ for $r>R$.  In addition:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
 \item in noncompact type, $G(r)/\sinh r$ is nonincreasing on $(0,\infty)$;
 \item in compact type, $G(r)/(\sin r\cos r)$ is nonincreasing on
 $(0,\pi/4)$.
\end{enumerate}
Consequently, the two angular weights in
\eqref{eq:A-compact} or \eqref{eq:A-noncompact}, after multiplication by
$G^2$, are nonincreasing on the relevant interval.

\label{cor:hopf-algebra}
For every $X\in\operatorname{Sym}(V)$,
\begin{equation}\label{eq:C-trace}
  \operatorname{tr}\mathcal C(X)=(k-1)\operatorname{tr} X
\end{equation}
and
\begin{equation}\label{eq:C-quadratic-bound}
  \operatorname{tr}\bigl(X\mathcal C(X)\bigr)\le(k-1)\operatorname{tr}(X^2).
\end{equation}
Moreover,
\begin{equation}\label{eq:isotropy-identities}
 \int_{S(V)}P_\xi\,\mathrm d\sigma(\xi)=\frac{|\mathbb S^{m-1}|}{m}I,
 \qquad
 \int_{S(V)}Q_\xi\,\mathrm d\sigma(\xi)
 =\frac{(k-1)|\mathbb S^{m-1}|}{m}I.
\end{equation}

\label{rem:constant-curvature-endpoints}
When $k=1$, $Q_\xi=0$ and $\mathcal C=0$.  When $n=1$, the horizontal space
vanishes and $Q_\xi=I-P_\xi$.  Thus, for any scalar function $b(\xi)$
with zero spherical mean,
\begin{equation}\label{eq:n-one-W-minus-Z}
  \int_{S(V)}b(\xi)Q_\xi\,\mathrm d\sigma(\xi)
  =-\int_{S(V)}b(\xi)P_\xi\,\mathrm d\sigma(\xi).
\end{equation}
These are precisely the constant-curvature endpoint cases in the compact
argument.

\label{lem:trace-ritz}
Let $\Omega$ be connected, and let $P_1,\ldots,P_m\in H^1(\Omega)$ be
linearly independent in $L^2(\Omega)$ and satisfy
$\int_\Omega P_i\,\mathrm dv=0$.  Define
\begin{equation}\label{eq:mass-stiffness-def}
  M_{ij}=\int_\Omega P_iP_j\,\mathrm dv,
  \qquad
  K_{ij}=\int_\Omega\left\langle \nabla P_i,\nabla P_j\right\rangle\,\mathrm dv.
\end{equation}
Then $M$ and $K$ are positive definite, and
\begin{equation}\label{eq:trace-ritz}
  \sum_{j=1}^{m}\frac1{\mu_j(\Omega)}
  \ge \operatorname{tr}(K^{-1}M).
\end{equation}

\label{lem:weinberger-center}
Let $G$ be the function in \eqref{eq:G-extension}.  In noncompact type
there exists $o\in M$ such that
\begin{equation}\label{eq:center-vector}
  \int_\Omega G(r_o(x))\xi_o(x)\,\mathrm dv(x)=0.
\end{equation}
In compact type, under \cref{ass:compact-localization}, such a point can be
chosen in the closed containing ball
$\overline{B_{i(M)/4}(q)}$.  Consequently
$r_o(x)\le\pi/4$ for $x\in\Omega$.

\label{prop:stiffness-comparison}
With $a,c,Z,W$ as above, the following estimates hold.

In noncompact type,
\begin{equation}\label{eq:K-upper-noncompact}
  K\preceq \lambda_RaI-dZ-eW
  =\lambda_RaI-dZ-e\mathcal C(Z),
\end{equation}
where
\begin{equation}\label{eq:d-e-noncompact}
  d=\frac{c}{\sinh^2R},
  \qquad e=\frac{c}{\cosh^2R}.
\end{equation}

In compact type,
\begin{equation}\label{eq:K-upper-compact}
  K\preceq \lambda_RaI-dZ+eW
  =\lambda_RaI-dZ+e\mathcal C(Z),
\end{equation}
where
\begin{equation}\label{eq:d-e-compact}
  d=\frac{c}{\sin^2R},
  \qquad e=\frac{c}{\cos^2R}.
\end{equation}

\label{lem:stiffness-rigidity}
Let $T_\pm$ denote the right-hand side of
\eqref{eq:K-upper-noncompact} or \eqref{eq:K-upper-compact}, respectively.
If $K=T_\pm$, then
\begin{equation}\label{eq:ray-ball-ae}
  E_\xi=(0,R)
  \quad\text{modulo }J(r)\,\mathrm d r\text{-null sets for a.e. }\xi.
\end{equation}
Consequently $|\Omega\triangle B_R(o)|=0$.  If $\Omega$ has smooth
boundary, then $\Omega=B_R(o)$.

\label{lem:aligned-closure}
Let $a,c,d,\lambda>0$ and $Z\in\operatorname{Sym}_m$ with $\operatorname{tr} Z=0$.  Suppose
\begin{equation}\label{eq:aligned-hypotheses}
 M\succeq0,
 \qquad M\succeq aI+cZ,
 \qquad 0<K\preceq\lambda aI-dZ.
\end{equation}
Then
\begin{equation}\label{eq:aligned-conclusion}
  \operatorname{tr}(K^{-1}M)\ge\frac m\lambda.
\end{equation}
If equality holds, then $Z=0$, $M=aI$, and $K=\lambda aI$.

\label{lem:positive-projection-jensen}
Let $\Pi:\operatorname{Sym}_m\to\operatorname{Sym}_m$ be positive, unital, trace-preserving,
Hilbert--Schmidt self-adjoint, and idempotent, and assume its
complex-linear extension is positive.  Let $X\in\operatorname{Sym}_m$ satisfy
$\operatorname{tr} X=0$.  If $u,v>0$ and
\begin{equation}\label{eq:projection-T}
  T=I-uX-v\Pi X\succ0,
\end{equation}
then
\begin{equation}\label{eq:positive-projection-jensen}
  \operatorname{tr}\bigl(T^{-1}(I+X)\bigr)\ge m.
\end{equation}
Equality holds if and only if $X=0$.

\label{lem:positive-mass-closure}
Let $X\in\operatorname{Sym}_m$ satisfy $\operatorname{tr} X=0$ and put $A=I+X$.  Suppose
$\widehat M,T\in\operatorname{Sym}_m$ satisfy
\begin{equation}\label{eq:positive-mass-hypotheses}
 \widehat M\succeq0,
 \qquad \widehat M\succeq A,
 \qquad 0<T\preceq2I,
 \qquad \operatorname{tr}(TA)\le m.
\end{equation}
Then
\begin{equation}\label{eq:positive-mass-conclusion}
  \operatorname{tr}(T^{-1}\widehat M)\ge m.
\end{equation}

By \cref{lem:trial-admissible,lem:trace-ritz},
\begin{equation}\label{eq:noncompact-ritz-start}
  \sum_{j=1}^{m}\frac1{\mu_j(\Omega)}
  \ge\operatorname{tr}(K^{-1}M).
\end{equation}
Let
\begin{equation}\label{eq:T0-noncompact}
  T_0=\lambda_RaI-dZ-e\mathcal C(Z).
\end{equation}
By \eqref{eq:K-upper-noncompact}, $0<K\preceq T_0$, and hence $T_0\succ0$.
Since inversion reverses Loewner order and $M\succeq0$,
\[
  \operatorname{tr}(K^{-1}M)\ge\operatorname{tr}(T_0^{-1}M).
\]
The mass comparison \eqref{eq:M-lower} and $T_0^{-1}\succ0$ then give
\begin{equation}\label{eq:noncompact-two-order-steps}
  \operatorname{tr}(K^{-1}M)
  \ge\operatorname{tr}\bigl(T_0^{-1}(aI+cZ)\bigr).
\end{equation}

Use the normalized matrix $X=cZ/a$ and set
\begin{equation}\label{eq:alpha-beta-noncompact}
  \alpha=\frac{d}{\lambda_Rc}
  =\frac1{\lambda_R\sinh^2R},
  \qquad
  \beta=\frac{e}{\lambda_Rc}
  =\frac1{\lambda_R\cosh^2R}.
\end{equation}
Because $\mathcal C=k\Pi-I$,
\begin{align*}
 T_0
 &=\lambda_Ra\bigl(I-\alpha X-\beta\mathcal C(X)\bigr)\\
 &=\lambda_Ra\bigl(I-(\alpha-\beta)X-k\beta\Pi X\bigr).
\end{align*}
Here $u:=\alpha-\beta>0$ and $v:=k\beta>0$.  Therefore
\cref{lem:positive-projection-jensen} yields
\begin{align*}
 \operatorname{tr}\bigl(T_0^{-1}(aI+cZ)\bigr)
 &=\frac1{\lambda_R}
 \operatorname{tr}\left[(I-uX-v\Pi X)^{-1}(I+X)\right]\\
 &\ge\frac m{\lambda_R}.
\end{align*}
Together with \eqref{eq:noncompact-ritz-start} and
\eqref{eq:noncompact-two-order-steps}, this proves
\eqref{eq:main-noncompact}.

Suppose equality holds.  Then equality must hold at every stage of the
preceding chain.  The equality statement in
\cref{lem:positive-projection-jensen} gives $X=0$, hence $Z=0$ and
$T_0=\lambda_RaI$.  Equality in the mass trace comparison gives
$M=aI$.  Since $M\succ0$, equality in the inverse-order comparison gives
$K=T_0$.  Thus equality holds in the stiffness comparison, and
\cref{lem:stiffness-rigidity} implies $\Omega=B_R(o)$.  Conversely, on a
geodesic ball the first nonzero eigenvalue has multiplicity $m$, and the
claimed equality is immediate.

\label{def:hopf-balanced}
The Weinberger center $o$ is called \emph{Hopf-balanced} if the angular
imbalance matrix in \eqref{eq:Z-def} satisfies
\begin{equation}\label{eq:hopf-balanced}
  \Pi Z=0.
\end{equation}

\label{lem:imbalance-realization}
Let $A\in\operatorname{Sym}(V)$ be trace-free.  For every $R$ strictly below the maximal
polar radius under consideration, there are smooth, centrally symmetric,
star-shaped domains $\Omega_\varepsilon$ with $|\Omega_\varepsilon|=|B_R|$ such that
\begin{equation}\label{eq:Z-realization}
  Z_\varepsilon=\frac{2|\mathbb S^{m-1}|}{m(m+2)}\varepsilon A.
\end{equation}
For sufficiently small $|\varepsilon|$, the domains remain in the same compact
localization ball whenever $R<\pi/8$.
